import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import axios from 'axios';  // NEW: For API calls (install with npm install axios)
import '../index.css'; // <- Keep your existing path

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);  // NEW: Optional loading state
  const navigate = useNavigate();

  const API_BASE = 'http://127.0.0.1:8000';

  async function handleSubmit(e) {  // UPDATED: Now async for API call
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      // NEW: Call backend login endpoint instead of localStorage check
      const response = await axios.post(`${API_BASE}/login`, {
        email,
        password,
      });

      // NEW: On success, store JWT and role
      const { access_token, role } = response.data;
      localStorage.setItem('authToken', access_token);  // Store JWT for authenticated requests
      localStorage.setItem('userRole', role);  // Store role for UI logic

      alert('Login successful!');  // Keep your alert

      // UPDATED: Always navigate to dashboard (profiles assumed created on signup)
      navigate('/dashboard');
    } catch (err) {
      // NEW: Handle backend errors
      const errorMessage = err.response?.data?.detail || 'Login failed. Please try again.';
      setError(errorMessage);
    } finally {
      setLoading(false);  // NEW: Reset loading
    }
  }

  return (
    <div className="auth-page">
      <div className="auth-container">
        <h1>SoftScale</h1>
        <form onSubmit={handleSubmit}>
          <input
            type="email"
            placeholder="Email address"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />

          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />

          {error && <div style={{ color: '#cc3b3b', marginTop: 8 }}>{error}</div>}

          <button type="submit" disabled={loading}>  {/* UPDATED: Disable during loading */}
            {loading ? 'Logging in...' : 'Login'}
          </button>
        </form>
        <p>
          Don't have an account? <Link to="/signup">Sign up</Link>
        </p>
      </div>
    </div>
  );
}
